#!/usr/bin/env bash
# T22-v2 diagnosis step 1: copy preserved scratch work trees, recompile each with --print-acir using the pinned nargo,
# and compare regenerated bytecode/ABI with the preserved targets. The source scratch tree is only read.
#
# Usage: bash scripts/t22_diag_recompile.sh SRC_SCRATCH DST_SCRATCH OUT_DIR
#   e.g. bash scripts/t22_diag_recompile.sh build/T22/scratch-31_v2_primary build/T22/scratch-32_v2_diagnosis \
#          results/raw/T22/32_v2_diagnosis
# Writes OUT_DIR/00_manifest.txt, OUT_DIR/01_recompile.txt and OUT_DIR/acir/<work>.{acir,stderr}.txt; refuses to overwrite.
set -uo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$ROOT"
SRC="$1"; DST="$2"; OUT="$3"
NARGO="${NARGO:-$ROOT/tools/noir-1.0.0-beta.14/nargo}"
CVC5="${CVC5:-$ROOT/tools/cvc5-1.4.2-gpl/bin/cvc5}"

for f in "$OUT/00_manifest.txt" "$OUT/01_recompile.txt" "$OUT/acir"; do
  if [ -e "$f" ]; then echo "refusing to overwrite $f" >&2; exit 1; fi
done
if [ -e "$DST" ]; then echo "refusing to reuse existing scratch copy $DST" >&2; exit 1; fi
mkdir -p "$OUT/acir" "$DST"

{
  echo "date_utc=$(date -u +%FT%TZ)"; echo "host=$(uname -srm)"
  echo "repository_head=$(git rev-parse HEAD)"; echo "worktree_note=uncommitted T22 changes may be present; analyzer hashes below"
  echo "nargo=$("$NARGO" --version | tr '\n' ' ')"
  echo "cvc5=$("$CVC5" --version | head -1)"
  echo "python=$(python3 --version)"
  echo "source_scratch=$SRC (read-only; copied)"
  sha256sum scripts/t22_tailspec.py scripts/t22_eval.py scripts/t22.sh scripts/t22_specs/payy_agg_agg.json scripts/t22_specs/payy_agg_utxo.json
} > "$OUT/00_manifest.txt"

field_hash() {  # field_hash JSON_FILE bytecode|abi
  python3 -I -c 'import json,sys
d=json.load(open(sys.argv[1]))
print(d["bytecode"] if sys.argv[2]=="bytecode" else json.dumps(d["abi"],sort_keys=True))' "$1" "$2" | sha256sum | cut -d' ' -f1
}

for d in "$SRC"/work_*; do cp -a "$d" "$DST"/; done
for d in "$DST"/work_*; do
  c=$(basename "$d"); pkg=$(ls "$d/noir/target/" | sed 's/.json//')
  sha_old=$(sha256sum "$SRC/$c/noir/$pkg/src/main.nr" | cut -d' ' -f1)
  (cd "$d/noir" && "$NARGO" compile --package "$pkg" --print-acir > "$ROOT/$OUT/acir/$c.acir.txt" 2> "$ROOT/$OUT/acir/$c.stderr.txt"); st=$?
  b_old=$(field_hash "$SRC/$c/noir/target/$pkg.json" bytecode); b_new=$(field_hash "$d/noir/target/$pkg.json" bytecode)
  a_old=$(field_hash "$SRC/$c/noir/target/$pkg.json" abi); a_new=$(field_hash "$d/noir/target/$pkg.json" abi)
  echo "$c pkg=$pkg exit=$st main_nr=$sha_old bytecode_same=$([ "$b_old" = "$b_new" ] && echo yes || echo NO) abi_same=$([ "$a_old" = "$a_new" ] && echo yes || echo NO) acir_txt=$(sha256sum "$OUT/acir/$c.acir.txt" | cut -d' ' -f1)"
done | tee "$OUT/01_recompile.txt"
